33	    owner: string;
34	    repositoryName: string;
35	  }>();
36	  const [repository, setRepository] = useState<RepositoryDetails | null>(null);
37	  const [issues, setIssues] = useState<RepositoryIssue[]>([]);
38	  const [currentPage, setCurrentPage] = useState(1);
39	  const [isLoadingMore, setIsLoadingMore] = useState(false);
40	  const [hasMore, setHasMore] = useState(true);
41	
42	  useEffect(() => {
43	    getRepositoryDetails
44	      .get(owner, repositoryName)
45	      .then((repository) => {
46	        setRepository(repository);
47	      })
48	      .catch(() => {
49	        setRepository(null);
50	      });
