52	    getRepositoryIssues
53	      .get(owner, repositoryName, 1)
54	      .then((issues) => {
55	        setIssues(issues);
56	        setCurrentPage(1);
57	        setHasMore(issues.length > 0);
58	      })
59	      .catch(() => {
60	        setIssues([]);
61	        setHasMore(false);
62	      });
