70	      if (newIssues.length === 0) {
71	        setHasMore(false);
72	      } else {
73	        setIssues((prev) => [...prev, ...newIssues]);
74	        setCurrentPage(nextPage);
75	      }
76	    } catch {
77	      setHasMore(false);
78	    } finally {
79	      setIsLoadingMore(false);
80	    }
81	  };
