93	        <RespositoryInfo>
94	          <header>
95	            <img src={repository.owner.avatar} alt="Owner profile avatar" />
96	            <div>
97	              <strong>{repository.name}</strong>
98	              <p>{repository.description}</p>
99	            </div>
100	          </header>
101	          <ul>
102	            <li>
103	              <strong>{repository.stars}</strong>
104	              <span>Stars</span>
105	            </li>
106	            <li>
107	              <strong>{repository.forks}</strong>
108	              <span>Forks</span>
109	            </li>
110	            <li>
111	              <strong>{repository.issues}</strong>
112	              <span>Open issues</span>
113	            </li>
114	          </ul>
115	        </RespositoryInfo>
116	      ) : (
117	        <p>Loading information.</p>
118	      )}
119	
120	      <Issues>
121	        {issues.map((issue) => (
122	          <a key={issue.id} href={issue.linkTo}>
123	            <div>
124	              <strong>{issue.title}</strong>
125	              <p>{issue.createdBy}</p>
126	            </div>
127	            <FiChevronRight size={20} />
128	          </a>
129	        ))}
130	        {hasMore && (
131	          <button
132	            onClick={handleLoadMore}
133	            disabled={isLoadingMore}
134	          >
135	            {isLoadingMore ? "Carregando..." : "Carregar mais"}
136	          </button>
137	        )}
138	      </Issues>
139	
140	      <Footer />
141	    </>
142	  );
143	};
